        max: Optional['types.CertificationMaxAggregateInput'] = None,
        having: Optional['types.CertificationScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.CertificationCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.CertificationScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.CertificationScalarFieldKeys', 'types.SortOrder']]]] = None,
